"""Calibrate conditional intact-word slot controls on open practice material."""
from collections import defaultdict
import json
from vs import corpus, dsl, gaps
from decompose import scenario, null_test

def groups(rows, tokens, stride):
    output=[]
    for line in rows:
        bins=defaultdict(list)
        for i in line[1:-1]:
            token=tokens[i]
            word=token['w']
            key=() if stride=='edge_only' else (len(word),) if stride=='length' else (len(word),word.count('o'))
            bins[key].append(i)
        output.extend(x for x in bins.values() if len(x)>=2)
    return output

def run():
    ps={n:corpus.split_pages('practice',n)[1] for n in ('zl','it','rf')}
    pools={n:gaps.eligible_line_ids(p) for n,p in ps.items()}
    shared=pools['zl']&pools['it']
    out={}
    for n in ('zl','it'):
        p=ps[n]
        out[n]={}
        for layout, ids in [('native',pools[n]),('paired',shared)]:
            ts=dsl.tokens(scenario(p,ids))
            words=[t['w'] for t in ts]
            geometry=dsl._paragraph_gap_groups(ts)
            rows=dsl._paragraph_gap_groups(ts,by_line=True)
            out[n][layout]={}
            for stride in ('edge_only','length','length_and_o_count'):
                g=groups(rows,ts,stride)
                moving=sum(len(q) for q in g if len({words[i] for i in q})>=2)
                out[n][layout][stride]=dict(groups=len(g),potentially_moved_words=moving,
                     **null_test(words,geometry,g,n=399,seed=408))
    return out

print(json.dumps(run(),indent=2))

