from pathlib import Path
from random import Random
from statistics import mean
from vs import dsl, gaps, ivtff, split

RAW = Path.cwd() / 'voynich-data-checkout-fix/data/raw'
editions = ('ZL3b-n.txt', 'IT2a-n.txt', 'RF1b-e.txt')
zl = ivtff.parse(RAW / editions[0])
public = set(split.select('practice',zl))
ps = {f: [p for p in ivtff.parse(RAW / f) if p.id in public] for f in editions}
sets = {f: gaps.eligible_line_ids(pages) for f,pages in ps.items()}

def raw_groups(pages, retained):
    groups=[]
    for page in pages:
        run=[]
        for line in page.lines:
            if line.unit!='P':
                continue
            keep=line.id in retained
            if (line.para_start or not keep) and run:
                groups.append(run)
                run=[]
            if keep:
                run.append(line.words)
            if line.para_end and run:
                groups.append(run)
                run=[]
        if run:
            groups.append(run)
    return groups

def stat(runs):
    curve=gaps.gap_curve((gaps.hit_positions(run,'o') for run in runs),gaps.SHORT_LAGS)
    return mean(c for c,_ in curve.values()),{lag:n for lag,(_,n) in curve.items()}

def flat(rows):
    return [w for row in rows for w in row]

def shuffled(rows,rng,line):
    parts=[list(row) for row in rows] if line else [flat(rows)]
    for words in parts:
        rng.shuffle(words)
    return flat(parts)

masks = [('paired', sets[editions[0]] & sets[editions[1]],editions[:2]),
         ('all-three', set.intersection(*sets.values()),editions)]
for scope,kept,eds in masks:
    for f in eds:
        runs=raw_groups(ps[f],kept)
        observed,pairs=stat([flat(r) for r in runs])
        row={'eligible':len(kept),'runs':len(runs),'observed':observed,'pairs':pairs}
        for by_line in [False,True]:
            rng=Random(408)
            draw=[]
            for _ in range(400):
                null,support=stat([shuffled(r,rng,by_line) for r in runs])
                assert support==pairs
                draw.append(null)
            row['line' if by_line else 'para']=(mean(draw),(1+sum(x>=observed for x in draw))/401)
        print(scope,f,row,flush=True)
